import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"OCSE——OpenCubeOS 安装环境：架构与职责","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocse/ocse-architecture.md","filePath":"zh/components/ocse/ocse-architecture.md"}'),r={name:"zh/components/ocse/ocse-architecture.md"};function a(s,t,n,l,h,i){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="ocse——opencubeos-安装环境-架构与职责" tabindex="-1">OCSE——OpenCubeOS 安装环境：架构与职责 <a class="header-anchor" href="#ocse——opencubeos-安装环境-架构与职责" aria-label="Permalink to &quot;OCSE——OpenCubeOS 安装环境：架构与职责&quot;">​</a></h1><p>OCSE 是 Open Cube OS 的<strong>安装环境</strong>：一个从安装介质启动、把一台 空白机器变成可启动的 Open Cube OS 系统的独立小内核。它拥有自己的 源码树（<code>ocse/</code>）、自己的链接脚本（<code>ocse/linker_ocse.ld</code>），与运行 系统（OCOS）和恢复环境（OCIRE）不共享任何代码。</p><h2 id="为什么需要专门的安装内核" tabindex="-1">为什么需要专门的安装内核 <a class="header-anchor" href="#为什么需要专门的安装内核" aria-label="Permalink to &quot;为什么需要专门的安装内核&quot;">​</a></h2><p>安装必须在一台<strong>什么都没有</strong>的机器上成功——没有操作系统、没有 驱动、没有 shell。因此 OCSE 自带了它需要的一切的最小实现：</p><table tabindex="0"><thead><tr><th>模块</th><th>文件</th><th>职责</th></tr></thead><tbody><tr><td>内核核心</td><td><code>kernel/</code>、<code>boot/</code></td><td>独立启动、GUI/输入循环调度</td></tr><tr><td>屏幕</td><td><code>screen_fb</code></td><td>帧缓冲控制台 + GUI 控件层</td></tr><tr><td>输入</td><td>键盘驱动</td><td>菜单按键、文本框、热键</td></tr><tr><td>磁盘访问</td><td><code>ocse_disk.c</code>、<code>ocse_atapi.c</code></td><td>ATA/ATAPI 与 BIOS/UEFI 磁盘 I/O</td></tr><tr><td>分区</td><td><code>ocse_part.c</code>、<code>ocse_detect.c</code></td><td>MBR/GPT 解码、空闲间隙检测、既有系统检测</td></tr><tr><td>文件系统</td><td><code>fs/</code>、<code>ocse_mkfs.c</code>、<code>ocse_ext4w.c</code></td><td>FAT32/exFAT/ext4 的创建与读写</td></tr><tr><td>安装载荷</td><td><code>ocse_iso.c</code>、<code>ocse_inst.c</code></td><td>ISO9660 读取、安装状态机</td></tr><tr><td>完整性</td><td><code>ocse_sha256.c</code></td><td>SHA-256 摘要（介质检查、口令散列）</td></tr><tr><td>用户界面</td><td><code>ocse_gui.c</code>、<code>ocse_wizard.c</code>、<code>ocse_cl.c</code></td><td>面板、9 步向导、OCSECL shell</td></tr><tr><td>本地化</td><td><code>ocse_i18n.c</code></td><td>英文 / 简体中文，实时切换</td></tr></tbody></table><h2 id="安全模型" tabindex="-1">安全模型 <a class="header-anchor" href="#安全模型" aria-label="Permalink to &quot;安全模型&quot;">​</a></h2><p>OCSE 在设计上<strong>不可能意外破坏已有的 Open Cube OS 安装</strong>：</p><ul><li>对已经能启动 <code>opencube.elf</code> 的目标<strong>直接拒绝</strong>（既有系统 检查）——向导显示的是拒绝提示，而不是分区列表。</li><li>分区只使用目标盘上的<strong>最大空闲间隙</strong>；从不搬迁或删除他人 分区来腾地方。</li><li>格式化只作用于<strong>同一向导会话中 OCSE 自己创建的分区</strong>。</li><li>所有破坏性 OCSECL 命令（<code>mkpart</code>、<code>rmpart</code>、<code>mkfs.*</code>、 <code>install</code>、<code>ocbl-install</code>、<code>dd</code>）都要求末尾带字面 <code>confirm</code>。</li></ul><h2 id="内存纪律-ocsework-区" tabindex="-1">内存纪律：.ocsework 区 <a class="header-anchor" href="#内存纪律-ocsework-区" aria-label="Permalink to &quot;内存纪律：.ocsework 区&quot;">​</a></h2><p>全部可变安装状态都放在专门的 <code>.ocsework</code> NOLOAD 段——镜像的 其余部分是纯代码与常量。环境是独立实现（无 libc、无 printf）： 所有文本缓冲都经有界字符串助手构建，装不下的行会被明确拒绝， 绝不溢出（这是向导命令构建器缓冲溢出修复后确立的纪律）。</p><h2 id="启动与识别" tabindex="-1">启动与识别 <a class="header-anchor" href="#启动与识别" aria-label="Permalink to &quot;启动与识别&quot;">​</a></h2><p>安装介质是携带一个字节的 <code>/ocse.marker</code> 文件的 ISO9660 卷—— WP-06 安装介质契约。OCBL 引导加载器识别该标记并把介质列为 启动菜单中的 OCSE 条目。启动后 OCSE 运行四项硬件检查 （<code>hwcheck</code>），随后进入图形面板；OCSECL shell 随时可用一个 热键唤出。</p><h2 id="与其他组件的关系" tabindex="-1">与其他组件的关系 <a class="header-anchor" href="#与其他组件的关系" aria-label="Permalink to &quot;与其他组件的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>角色</th><th>参见</th></tr></thead><tbody><tr><td>OCBL</td><td>OCSE 所安装的引导加载器（<code>ocbl-install</code>）</td><td><a href="./../ocbl/">OCBL 总览</a></td></tr><tr><td>OCOS</td><td>OCSE 安装到目标上的系统</td><td>主手册</td></tr><tr><td>OCIRE</td><td>恢复环境，安装在 A/B 恢复盘上</td><td>开发者手册</td></tr></tbody></table><p>下一篇：<a href="./ocse-wizard.html">9 步安装向导与 OCSECL 命令字典</a>。</p>',15)])])}const b=e(r,[["render",a]]);export{p as __pageData,b as default};
